<h1>Hizmetler</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><div class="grid"><?php foreach($services as $s):?><section class="card"><span class="tag"><?=e($s['category'])?></span><h2><?=e($s['name'])?></h2><p><?=e($s['description'])?></p><b><?=money($s['price_per_1000'])?> / 1.000</b><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??=bin2hex(random_bytes(32)))?>"><input type="hidden" name="service_id" value="<?=$s['id']?>"><label>Bağlantı</label><input name="link" type="url" required><label>Miktar (<?=$s['min_qty']?>-<?=$s['max_qty']?>)</label><input name="quantity" type="number" min="<?=$s['min_qty']?>" max="<?=$s['max_qty']?>" required><button>Sipariş ver</button></form></section><?php endforeach?></div>
